from hypothesis import strategies as st


def _nbrs(p, N):
    # parts are 1..N on a ring
    return [p % N + 1, (p - 2) % N + 1]


def _bfs(start, blocked, N):
    # distances for one hand moving from `start` to every reachable part,
    # never stepping onto `blocked` (the other hand's part)
    dist = {start: 0}
    queue = [start]
    i = 0
    while i < len(queue):
        p = queue[i]
        i += 1
        for q in _nbrs(p, N):
            if q == blocked or q in dist:
                continue
            dist[q] = dist[p] + 1
