def _move_cost(pos, other, target, n):
    # Hand at `pos` must reach `target` without passing or entering `other`.
    # Exactly one of the two arcs avoids `other`; take its length.
    d_fwd = (target - pos) % n
    o_fwd = (other - pos) % n
    if o_fwd < d_fwd:
        # forward arc is blocked by the other hand, so go backward
        return n - d_fwd
    return d_fwd


