        best = None
        for i in range(n):
            if mask >> i & 1:
                d = dist(cur, pos[i])
                val = d + f(mask & ~(1 << i), i)
                if best is None:
                    best = val
                elif alice_turn:
                    best = max(best, val)
                else:
                    best = min(best, val)
        return best

